type IndexItem={id:string;mapId?:string|null;tema?:string;dimensionPladeco?:string;sector?:string;codigoContenedor?:string;temaTecnico?:string;nombre:string;carpeta?:string;geometria:string;escala?:string;contenedor?:string;tipoContenedor?:string;subcapa?:string;campoClave?:string;estado?:string;validacion?:string;registros?:number|string;crs?:string;anio?:string|number;areaDimension?:string;tematica?:string;rutaOrigen?:string;rutaDefinitiva?:string;observaciones?:string;verEnMapa:boolean;download:string};

