const pladecoDimensions=[
{id:"AMBIENTAL",label:"Dimensión Ambiental",sectors:["Áreas verdes y vegetación","Residuos, reciclaje y calidad ambiental"]},
{id:"URBANA",label:"Dimensión Urbana",sectors:["Planificación urbana y suelo","Movilidad e infraestructura"]},
{id:"SOCIOCULTURAL",label:"Dimensión Sociocultural",sectors:["Seguridad","Patrimonio y cultura","Turismo"]},
{id:"ECONOMICA",label:"Dimensión Económica",sectors:["Actividad económica y comercio"]},
{id:"INSTITUCIONAL",label:"Dimensión Institucional",sectors:["Gestión municipal y activos institucionales"]}
] as const;
function itemDimension(i:IndexItem){return (i as any).dimensionPladeco||"POR CLASIFICAR"}
function itemSector(i:IndexItem){return (i as any).sector||"Por clasificar"}
function gpkgDownload(i:IndexItem){
 const c=String(i.contenedor||"");
 if(c.toLowerCase().endsWith("_vf.gpkg"))return `/data/gpkg/${c}`;
 const d=normFieldName(`${itemDimension(i)} ${i.tema||""} ${i.carpeta||""}`);
 if(d.includes("ambiental")||d.includes("amb"))return "/data/gpkg/02_DIM_AMBIENTAL_VF.gpkg";
 if(d.includes("sociocultural")||d.includes("soc"))return "/data/gpkg/03_DIM_SOCIOCULTURAL_VF.gpkg";
 if(d.includes("economica")||d.includes("eco"))return "/data/gpkg/04_DIM_ECONOMICA_VF.gpkg";
 return ""
}

const PUBLIC_FIELD_HINTS=["direccion","domicilio","calle","ubicacion","address","nombre","nom","tipo","tipologia","categoria","clase","subtipo","sector","rango","range","tramo","nivel","estrato","quintil","decil","percentil","segmento","grupo","agrp","agrupacion","rubro","actividad","uso","destino","estado","condicion","modalidad","especie","ruta","servicio","equipamiento","recinto","barrio","territorio","comuna","zona","codigo","descripcion"];
const SENSITIVE_FIELD_HINTS=["rut","run","email","correo","mail","telefono","fono","celular","contacto","responsable","encargado","propietario","titular","dueno","dueño","apellido","fecha_nac","nacimiento","clave","password","contrasena","contraseña"];
function normFieldName(v:string){return v.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"_")}
function visualizationException(layer:Layer){const t=normFieldName(`${layer.id} ${layer.name} ${layer.source}`);return layer.id==="manzana"||t.includes("manzana_censo")||t.includes("sii")}
function sensitiveField(k:string){const n=normFieldName(k);return SENSITIVE_FIELD_HINTS.some(x=>n.includes(normFieldName(x)))}
function descriptorField(k:string){const n=normFieldName(k);return PUBLIC_FIELD_HINTS.some(x=>n===x||n.startsWith(`${x}_`)||n.endsWith(`_${x}`)||n.includes(`_${x}_`))}
function publicVisualizationFields(layer:Layer,fc:GeoCollection){const f=fc.features[0];if(!f)return[];const keys=Object.keys(f.properties||{});if(visualizationException(layer))return keys;const safe=keys.filter(k=>!sensitiveField(k));const preferred=safe.filter(descriptorField);return (preferred.length?preferred:safe.slice(0,6)).slice(0,12)}


