function distanceMeters(a:number[],b:number[]){const r=6371008.8,p1=a[1]*Math.PI/180,p2=b[1]*Math.PI/180,dp=(b[1]-a[1])*Math.PI/180,dl=(b[0]-a[0])*Math.PI/180,h=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;return 2*r*Math.asin(Math.sqrt(h))}
function uniqueNames(fc:GeoCollection|undefined,keys:string[]){return[...new Set((fc?.features??[]).map(f=>keys.map(k=>f.properties?.[k]).find(v=>v!=null&&String(v).trim())).filter(Boolean).map(String))].sort()}
function featureLabel(f:GeoFeature,keys:string[]){return String(keys.map(k=>f.properties?.[k]).find(v=>v!=null&&String(v).trim())??"Sin nombre")}
function breakdown(points:GeoCollection|undefined,polys:GeoCollection|undefined,keys:string[]){const out:Record<string,number>={};if(!points||!polys)return out;for(const p of polys.features){if(p.geometry.type!=="Polygon"&&p.geometry.type!=="MultiPolygon")continue;const name=featureLabel(p,keys);out[name]=(out[name]??0)+points.features.filter(x=>intersectsPolygon(x.geometry,p.geometry as any)).length}return out}
function normText(v:string){return v.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," ").replace(/\s+/g," ").trim()}
function resolveNamedScope(query:string,data:Record<string,GeoCollection>){const q=normText(query),defs=[{id:"territorio",level:"territorio",keys:["SECTORES_T","NOM_TERR","TERRITORIO","NOMBRE"]},{id:"barrio",level:"barrio",keys:["BARRIO","NOM_BARRIO","NOMBRE"]},{id:"manzana",level:"manzana",keys:["COD_MZN","cod_mzn"]}];for(const d of defs)for(const f of data[d.id]?.features??[]){if(f.geometry.type!=="Polygon"&&f.geometry.type!=="MultiPolygon")continue;const name=featureLabel(f,d.keys);if(name!=="Sin nombre"&&q.includes(normText(name))){const counts:Record<string,number>={};for(const l of layers)counts[l.id]=(data[l.id]?.features??[]).filter(x=>intersectsPolygon(x.geometry,f.geometry as any)).length;const nper=(data.manzana?.features??[]).filter(x=>intersectsPolygon(x.geometry,f.geometry as any)).reduce((z,x)=>z+(Number(x.properties.n_per)||0),0);return{level:d.level,name,counts,nper}}}return null}

