 const[modal,setModal]=useState<"table"|"meta"|"report"|"help"|null>(null);const[downloadRequest,setDownloadRequest]=useState<{path:string;label:string}|null>(null);const[downloadKey,setDownloadKey]=useState("");const[downloadError,setDownloadError]=useState("");

